       (SUM(?gorgonStr) / COUNT(?gorgon)) AS ?gorgon
WHERE {
  ?dhampir a :Beast ;
           :beastCategoryName "Dhampir" ;
           :str ?dhampirStr .
  ?gorgon a :Beast ;
          :beastCategoryName "Gorgon" ;
          :str ?gorgonStr .
}
```

