    <http://valuenet/ontop/surfacearea> ?area ;
    <http://valuenet/ontop/population> ?population ;
    <http://valuenet/ontop/continent> "North America" .
  FILTER(?area > 3000)
}

PREFIX : <http://valuenet/ontop/>
SELECT (SUM(?population) AS ?totalPopulation) (AVG(?surfacearea) AS ?averageSurfaceArea)
WHERE {
  ?country a <http://valuenet/ontop/country> ;
    <http://valuenet/ontop/surfacearea> ?surfacearea ;
    <http://valuenet/ontop/population> ?population ;
    <http://valuenet/ontop/continent> "North America" .
  FILTER (?surfacearea > 3000)
}

PREFIX : <http://valuenet/ontop/>
SELECT ?city ?population
WHERE {
  ?city a <http://valuenet/ontop/city> ;
        <http://valuenet/ontop/population> ?population .
  FILTER ( ?population >= 160000 && ?population <= 900000 )
}

PREFIX : <http://valuenet/ontop/>
SELECT DISTINCT ?name
WHERE {
  ?city a <http://valuenet/ontop/city> ;
        <http://valuenet/ontop/name> ?name ;
        <http://valuenet/ontop/population> ?population .
  FILTER ( ?population >= 160000 && ?population <= 900000 )
}

PREFIX : <http://valuenet/ontop/>
SELECT ?language (COUNT(?country) AS ?countryCount)
WHERE {
  ?countrylanguage <http://valuenet/ontop/language> ?language ;
                   <http://valuenet/ontop/ref-countrycode> ?country .
}
GROUP BY ?language
ORDER BY DESC(?countryCount)
LIMIT 1

PREFIX : <http://valuenet/ontop/>
SELECT ?country ?language ?percentage
WHERE {
  ?countrylanguage <http://valuenet/ontop/percentage> ?percentage .
  ?countrylanguage <http://valuenet/ontop/country> ?country ;
                  <http://valuenet/ontop/language> ?language .
  ?countrylanguage <http://valuenet/ontop/percentage> ?percentage .
  ?countrylanguage <http://valuenet/ontop/percentage> (MAX ?percentage) .
}

PREFIX : <http://valuenet/ontop/>
SELECT ?countryCode ?language ?maxPercentage
WHERE {
  ?country <http://valuenet/ontop/countrycode> ?countryCode .
  ?countrylanguage <http://valuenet/ontop/countrycode> ?countryCode ;
                  <http://valuenet/ontop/language> ?language ;
                  <http://valuenet/ontop/percentage> ?percentage .

  GROUP BY ?countryCode ?language
  ORDER BY DESC(?percentage)
  LIMIT 1
}

PREFIX : <http://valuenet/ontop/>
SELECT (COUNT(DISTINCT ?countrycode) AS ?totalCountries)
WHERE {
  ?countrylanguage a <http://valuenet/ontop/countrylanguage> ;
                  <http://valuenet/ontop/countrycode> ?countrycode ;
                  <http://valuenet/ontop/language> "Spanish" ;
                  <http://valuenet/ontop/percentage> ?percentage .
  FILTER (?percentage = (MAX(?percentage)))
}

PREFIX : <http://valuenet/ontop/>
SELECT (COUNT(DISTINCT ?countrycode) AS ?count)
WHERE {
  ?countrylanguage <http://valuenet/ontop/countrycode> ?countrycode ;
                   <http://valuenet/ontop/language> "Spanish" ;
                   <http://valuenet/ontop/percentage> ?percentage .
  FILTER (?percentage > 50)
}

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX : <http://valuenet/ontop/>
SELECT DISTINCT ?code
WHERE {
  ?countrylanguage a <http://valuenet/ontop/countrylanguage> ;
                  <http://valuenet/ontop/language> ?language ;
                  <http://valuenet/ontop/percentage> ?percentage .
  ?country a <http://valuenet/ontop/country> ;
           <http://valuenet/ontop/code> ?code .
  ?countrylanguage <http://valuenet/ontop/ref-countrycode> ?country .
  ?language = "Spanish"^^xsd:string .
  ?percentage = "100"^^xsd:float .
}
